export const ANIMATIONS_CSS = "/* Luci mascot animations. Works on the layered SVGs (inline) or inside the animated SVG files. */\n.luci .luci-ear,.luci .luci-eye,.luci .luci-tail,.luci .luci-body,.luci .luci-head,.luci .luci-z,.luci .luci-pupil,.luci .luci-arm,.luci .luci-ruler-line{transform-box:fill-box}\n.luci .luci-ear-l{transform-origin:70% 100%}\n.luci .luci-ear-r{transform-origin:30% 100%}\n.luci .luci-eye{transform-origin:50% 50%}\n.luci .luci-body{transform-origin:50% 100%}\n.luci .luci-head{transform-origin:50% 85%}\n.luci .luci-tail-wrap{transform-origin:92% 20%}\n.luci .luci-tail-up{transform-origin:5% 95%}\n.luci .luci-arm{transform-origin:10% 90%}\n.luci .luci-z{transform-origin:50% 50%}\n\n@keyframes luci-breathe{0%,100%{transform:scaleY(1)}50%{transform:scaleY(1.025)}}\n@keyframes luci-blink{0%,90%,100%{transform:scaleY(1)}94%{transform:scaleY(.08)}}\n@keyframes luci-slowblink{0%,25%{transform:scaleY(1)}42%,68%{transform:scaleY(.08)}85%,100%{transform:scaleY(1)}}\n@keyframes luci-twitch{0%,86%,100%{transform:rotate(0)}89%{transform:rotate(-12deg)}92%{transform:rotate(5deg)}95%{transform:rotate(-6deg)}98%{transform:rotate(0)}}\n@keyframes luci-sway{0%,100%{transform:rotate(-2.5deg)}50%{transform:rotate(2.5deg)}}\n@keyframes luci-lash{0%{transform:rotate(-9deg)}100%{transform:rotate(9deg)}}\n@keyframes luci-look{0%,18%{transform:translateX(0)}30%,50%{transform:translateX(-4px)}62%,82%{transform:translateX(4px)}94%,100%{transform:translateX(0)}}\n@keyframes luci-z{0%{opacity:0;transform:translate(0,6px) scale(.8)}25%{opacity:1}100%{opacity:0;transform:translate(10px,-20px) scale(1.1)}}\n@keyframes luci-tap{0%,100%{transform:rotate(0)}50%{transform:rotate(-7deg)}}\n@keyframes luci-pulse{0%,100%{opacity:1}50%{opacity:.3}}\n@keyframes luci-tilt{0%,100%{transform:rotate(0)}50%{transform:rotate(3deg)}}\n@keyframes luci-bristle{0%{transform:rotate(-2deg)}100%{transform:rotate(2deg)}}\n\n/* Idle: sitting tall */\n.luci-pose-sit .luci-body{animation:luci-breathe 4.5s ease-in-out infinite}\n.luci-pose-sit .luci-eye{animation:luci-blink 6s ease-in-out infinite}\n.luci-pose-sit .luci-ear-r{animation:luci-twitch 7s ease-in-out infinite}\n.luci-pose-sit .luci-tail{animation:luci-sway 5s ease-in-out infinite}\n/* Hello: slow blink (add class luci-hello to the sitting pose) */\n.luci-hello .luci-eye{animation:luci-slowblink 5s ease-in-out infinite}\n.luci-hello .luci-head{animation:luci-tilt 5s ease-in-out infinite}\n/* Avatar head */\n.luci-pose-head .luci-eye{animation:luci-blink 6s ease-in-out infinite}\n.luci-pose-head .luci-ear-l{animation:luci-twitch 8s ease-in-out infinite 2s}\n/* Watching (empty state) */\n.luci-pose-peek .luci-pupil{animation:luci-look 7s ease-in-out infinite}\n.luci-pose-peek .luci-eye{animation:luci-blink 7s ease-in-out infinite 3s}\n.luci-pose-peek .luci-ear-l{animation:luci-twitch 6s ease-in-out infinite 1s}\n/* Measuring (spacing tool) */\n.luci-pose-measure .luci-ruler-line{animation:luci-pulse 1.6s ease-in-out infinite}\n.luci-pose-measure .luci-arm{animation:luci-tap 1.6s ease-in-out infinite}\n.luci-pose-measure .luci-eye{animation:luci-blink 5s ease-in-out infinite}\n/* In the box (capture basket) */\n.luci-pose-box .luci-eye{animation:luci-blink 6s ease-in-out infinite}\n.luci-pose-box .luci-pupil{animation:luci-look 9s ease-in-out infinite 1s}\n.luci-pose-box .luci-ear-r{animation:luci-twitch 5s ease-in-out infinite}\n/* Asleep (loading) */\n.luci-pose-sleep .luci-body{animation:luci-breathe 3.5s ease-in-out infinite}\n.luci-pose-sleep .luci-z1{animation:luci-z 3s ease-out infinite}\n.luci-pose-sleep .luci-z2{animation:luci-z 3s ease-out infinite 1.5s}\n/* Content (success) */\n.luci-pose-content .luci-body{animation:luci-breathe 4s ease-in-out infinite}\n.luci-pose-content .luci-tail{animation:luci-sway 6s ease-in-out infinite}\n.luci-pose-content .luci-ear-r{animation:luci-twitch 6s ease-in-out infinite 2s}\n/* Annoyed (error) */\n.luci-pose-annoyed .luci-tail{animation:luci-lash .9s ease-in-out infinite alternate}\n.luci-pose-annoyed .luci-ear{animation:luci-bristle .35s ease-in-out infinite alternate}\n.luci-pose-annoyed .luci-body{animation:luci-breathe 1.8s ease-in-out infinite}\n/* Turned away (not now) */\n.luci-pose-turned .luci-tail{animation:luci-sway 4s ease-in-out infinite}\n.luci-pose-turned .luci-ear-r{animation:luci-twitch 5s ease-in-out infinite}\n.luci-pose-turned .luci-head{animation:luci-tilt 6s ease-in-out infinite}\n\n@media (prefers-reduced-motion: reduce){.luci *{animation:none!important}}";
